{
  "name": "workspace",
  "version": "0.0.0",
  "license": "MIT",
  "scripts": {
    "preinstall": "node scripts/preinstall.cjs",
    "dev": "concurrently --kill-others-on-fail -n api,web -c cyan,yellow \"cross-env PORT=3001 pnpm --filter @workspace/api-server run dev\" \"cross-env API_PORT=3001 pnpm --filter @workspace/wildfire-app run dev\"",
    "offline": "node scripts/start-offline.mjs",
    "build": "pnpm run typecheck && pnpm -r --if-present run build",
    "typecheck:libs": "tsc --build",
    "typecheck": "pnpm run typecheck:libs && pnpm -r --filter \"./artifacts/**\" --filter \"./scripts\" --if-present run typecheck"
  },
  "private": true,
  "dependencies": {
    "@replit/connectors-sdk": "^0.4.1",
    "playwright": "^1.61.1"
  },
  "devDependencies": {
    "concurrently": "^10.0.3",
    "cross-env": "catalog:",
    "prettier": "^3.9.4",
    "typescript": "~5.9.3"
  }
}
